#include <string>

class Solution {
public:
    int minimumBuckets(std::string hamsters) {
        int n = hamsters.size();
        int ans = 0;
        int lastBucket = -2;

        for (int i = 0; i < n; ++i) {
            if (hamsters[i] == 'H') {
                if (lastBucket == i - 1) continue;
                if (i + 1 < n && hamsters[i + 1] == '.') {
                    ans++;
                    lastBucket = i + 1;
                } else if (i - 1 >= 0 && hamsters[i - 1] == '.') {
                    ans++;
                    lastBucket = i - 1;
                } else {
                    return -1;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int minimumBuckets(String hamsters) {
        int n = hamsters.length();
        int ans = 0;
        int lastBucket = -2;

        for (int i = 0; i < n; i++) {
            if (hamsters.charAt(i) == 'H') {
                if (lastBucket == i - 1) continue;
                if (i + 1 < n && hamsters.charAt(i + 1) == '.') {
                    ans++;
